insert into public.spots
  (source, source_id, title, category, area, address, lat, lng, image_url, overview, one_liner, theme_tags, indoor)
values
  ('sample', 'S001', '성산일출봉', '관광지', '동부', '제주특별자치도 서귀포시 성산읍', 33.4581, 126.9426, null, '바다 위로 솟은 분화구에 올라 일출을 보는 제주의 대표 명소입니다. 정상까지 계단길로 30분쯤 걸리며 유네스코 세계자연유산입니다.', '바다 위로 솟은 분화구에 올라 일출을 보는 제주의 대표 명소입니다.', array['바다','오름','사진']::text[], false),
  ('sample', 'S003', '만장굴', '관광지', '동부', '제주특별자치도 제주시 구좌읍', 33.5284, 126.7716, null, '용암이 흘러 만든 길이 수 킬로미터의 용암동굴입니다. 동굴 안은 일 년 내내 서늘하고 비가 와도 둘러볼 수 있습니다.', '용암이 흘러 만든 길이 수 킬로미터의 용암동굴입니다.', '{}'::text[], true),
  ('sample', 'S004', '협재해수욕장', '관광지', '서부', '제주특별자치도 제주시 한림읍', 33.394, 126.2397, null, '에메랄드빛 얕은 바다와 흰 모래, 건너편 비양도 풍경으로 사랑받는 해변입니다. 물이 얕아 아이와 놀기에도 좋습니다.', '에메랄드빛 얕은 바다와 흰 모래, 건너편 비양도 풍경으로 사랑받는 해변입니다.', array['바다','아이와']::text[], false),
  ('sample', 'S006', '천지연폭포', '관광지', '서귀포시', '제주특별자치도 서귀포시 천지동', 33.2469, 126.5544, null, '숲길을 따라 조금 걸으면 만나는 폭포입니다. 길이 평탄해 부모님과 함께 걷기 좋고 밤에도 조명이 켜집니다.', '숲길을 따라 조금 걸으면 만나는 폭포입니다.', array['숲','폭포']::text[], false),
  ('sample', 'S009', '오설록 티뮤지엄', '문화시설', '서부', '제주특별자치도 서귀포시 안덕면', 33.3059, 126.2895, null, '넓은 녹차밭 옆에 있는 차 박물관이자 카페입니다. 차 문화 전시를 보고 녹차 디저트를 맛볼 수 있습니다.', '넓은 녹차밭 옆에 있는 차 박물관이자 카페입니다.', array['박물관','카페']::text[], true),
  ('sample', 'S010', '아쿠아플라넷 제주', '문화시설', '동부', '제주특별자치도 서귀포시 성산읍', 33.4329, 126.9279, null, '대형 수조와 해양 생물 전시, 공연을 볼 수 있는 실내 아쿠아리움입니다. 비 오는 날 아이와 가기 좋은 곳으로 꼽힙니다.', '대형 수조와 해양 생물 전시, 공연을 볼 수 있는 실내 아쿠아리움입니다.', array['아이와']::text[], true),
  ('sample', 'S012', '국립제주박물관', '문화시설', '제주시', '제주특별자치도 제주시 건입동', 33.5136, 126.549, null, '선사 시대부터 근현대까지 제주의 역사와 문화를 전시하는 박물관입니다. 어린이 체험 전시실도 있습니다.', '선사 시대부터 근현대까지 제주의 역사와 문화를 전시하는 박물관입니다.', array['박물관','체험','역사','아이와']::text[], true),
  ('sample', 'S014', '사려니숲길', '관광지', '동부', '제주특별자치도 제주시 조천읍', 33.4259, 126.6373, null, '삼나무가 빽빽한 평탄한 숲길입니다. 경사가 거의 없어 천천히 걷기 좋고 안개 낀 날의 분위기가 특히 좋습니다.', '삼나무가 빽빽한 평탄한 숲길입니다.', array['숲']::text[], false),
  ('sample', 'S016', '새별오름', '관광지', '서부', '제주특별자치도 제주시 애월읍', 33.3663, 126.357, null, '가을 억새로 유명한 오름입니다. 20~30분이면 정상에 올라 제주 서쪽 들판과 바다를 내려다볼 수 있습니다.', '가을 억새로 유명한 오름입니다.', array['오름']::text[], false),
  ('sample', 'S018', '카멜리아힐', '관광지', '서부', '제주특별자치도 서귀포시 안덕면', 33.2898, 126.3704, null, '겨울 동백꽃으로 유명한 정원입니다. 계절마다 수국과 여러 꽃이 피어 사진 찍는 여행자가 많이 찾습니다.', '겨울 동백꽃으로 유명한 정원입니다.', array['사진']::text[], false),
  ('sample', 'S019', '동문재래시장', '쇼핑', '제주시', '제주특별자치도 제주시 이도일동', 33.512, 126.5283, null, '제주시에서 가장 큰 재래시장입니다. 해산물과 감귤, 야시장 먹거리를 구경하며 간단히 식사하기 좋습니다.', '제주시에서 가장 큰 재래시장입니다.', array['시장']::text[], false),
  ('sample', 'S059', '흑돼지거리', '음식점', '제주시', '제주특별자치도 제주시 건입동', 33.514, 126.527, null, '제주 흑돼지 구이 식당이 모여 있는 거리입니다. 동문시장과 가까워 시장 구경 뒤 저녁 식사 장소로 많이 찾습니다.', '제주 흑돼지 구이 식당이 모여 있는 거리입니다.', '{}'::text[], false)
